  const handleSelectExcuse = (reason: string, result: string) => {
    playErrorBuzz();

    if (result === "MEME_TRIGGER") {
      const randomMeme = MEMES[Math.floor(Math.random() * MEMES.length)];
      setActiveMeme(randomMeme);
      setSelectedExcuse(null);
      return;
    }

    setActiveMeme(null);
    setSelectedExcuse(result);
    playSternVoice(`System Alert: ${result}`);
