                        </div>
                    </div>
                    </div>

                    <form onSubmit={handleStartCheck} className="p-5 md:p-8 space-y-6 md:space-y-8 bg-slate-50">
                    <div className="flex justify-between items-center bg-blue-50 p-3 md:p-4 rounded-2xl border border-blue-100">
                        <span className="text-[10px] md:text-xs font-black text-blue-900 uppercase">Group Verification</span>
                        <button type="button" onClick={() => setIsGroupMode(!isGroupMode)} className={`w-12 h-6 md:w-14 md:h-7 rounded-full transition-all relative ${isGroupMode ? 'bg-blue-600' : 'bg-slate-300'}`}>
                        <div className={`absolute top-1 w-4 h-4 md:top-1.5 md:left-1.5 bg-white rounded-full transition-all ${isGroupMode ? 'left-7 md:left-8' : 'left-1'} shadow-md`} />
                        </button>
                    </div>

                    <div className="space-y-4 md:space-y-6 max-h-[40vh] md:max-h-[45vh] overflow-y-auto pr-1 md:pr-2 no-scrollbar">
                        {students.map((student, idx) => (
                        <div key={idx} className="p-4 md:p-6 bg-white border border-slate-200 rounded-2xl space-y-4 relative shadow-sm">
                            {idx > 0 && <button onClick={() => setStudents(students.filter((_, i) => i !== idx))} className="absolute top-3 right-3 text-red-500 font-bold text-[10px] p-2 hover:bg-red-50 rounded-lg">REMOVE</button>}
                            <div className="grid grid-cols-1 gap-3 md:gap-4">
                                <div>
                                    <label className="block text-[10px] font-black text-slate-400 uppercase mb-1">Full Name</label>
