                                <input required type="number" inputMode="numeric" value={student.attended || ''} onChange={e => { const n = [...students]; n[idx].attended = parseInt(e.target.value) || 0; setStudents(n); }} className="w-full bg-slate-100 border-none p-2.5 md:p-3 rounded-xl text-sm md:text-base text-black font-bold" />
                            </div>
                            </div>
                        </div>
                        ))}
                    </div>

                    {isGroupMode && (
                        <button type="button" onClick={() => setStudents([...students, { name: '', id: '', total: 0, attended: 0, pct: 0, status: 'Detained' }])} className="w-full py-3 md:py-4 border-2 border-dashed border-slate-300 text-slate-400 text-xs font-black hover:bg-slate-100 rounded-2xl transition-colors active:scale-98">
                        + ADD CLASSMATE
                        </button>
                    )}

                    <button type="submit" className="w-full bg-blue-900 text-white font-black py-4 md:py-5 rounded-2xl shadow-xl shadow-blue-900/30 hover:bg-blue-800 transition-all flex items-center justify-center gap-3 active:scale-95 text-sm md:text-base">
                        VERIFY LOGS
