                            {gameState === 'idle' && (
                            <>
                                <p className="text-white text-sm md:text-lg font-black uppercase leading-tight">Dodge 10 seconds of falling paperwork to appeal your detention.</p>
                                <button onClick={() => { setGameState('playing'); setGameTime(10); setAssignments([]); }} className="bg-cyan-500 text-black px-8 py-4 md:px-12 md:py-5 rounded-full font-black uppercase text-base md:text-lg shadow-xl shadow-cyan-500/30 active:scale-95 transition-transform">Begin Appeal</button>
                            </>
                            )}
                            {gameState === 'lost' && (
                            <>
                                <h3 className="text-red-600 text-4xl md:text-6xl font-black uppercase">F-Grade</h3>
                                <p className="text-white font-bold text-sm md:text-base">You were buried by assignments. Detainment upheld.</p>
                                <button onClick={() => setGameState('idle')} className="text-cyan-500 font-black border-b-2 border-cyan-500 uppercase tracking-widest py-1 text-sm md:text-base">Try Again</button>
                            </>
                            )}
                            {gameState === 'won' && (
                            <>
                                <h3 className="text-green-500 text-4xl md:text-6xl font-black uppercase italic">Phew!</h3>
                                <p className="text-white font-bold text-sm md:text-base">You survived the load! Your attendance has been recalibrated to...</p>
                                <div className="text-5xl md:text-7xl font-black text-red-500 animate-bounce">74.9%</div>
                                <p className="text-slate-500 font-black text-[10px] md:text-xs uppercase">"System Limitation: Still Failing."</p>
                                <button onClick={() => setStep('result')} className="bg-white text-black px-8 py-3 md:px-10 md:py-4 rounded-full font-black uppercase text-xs md:text-sm">Return to Logs</button>
                            </>
                            )}
                        </div>
                        )}
                    </div>
                    <button onClick={() => setStep('result')} className="text-slate-600 font-black uppercase text-[10px] md:text-xs tracking-[0.3em] hover:text-white transition-colors p-2">Abort Portal</button>
                 </div>
              </div>
            )}
        </div>

        <AnimatePresence>
          {showFakeCall && (
            <motion.div 
                initial={{ y: '100%' }} 
                animate={{ y: 0 }} 
                exit={{ y: '100%' }} 
                transition={{ type: 'spring', damping: 20, stiffness: 300 }}
                className="fixed bottom-0 left-0 right-0 bg-slate-900 border-t-2 border-slate-700 p-6 md:p-8 z-[200000] flex flex-col sm:flex-row items-center justify-between shadow-[0_-20px_50px_rgba(0,0,0,0.5)] gap-6 md:gap-8 rounded-t-[2rem] md:rounded-t-[3rem]"
            >
              {callStatus === 'incoming' ? (
                <>
                  <div className="flex items-center gap-4 md:gap-6 w-full sm:w-auto">
                    <div className="w-12 h-12 md:w-16 md:h-16 bg-red-500/20 rounded-full flex items-center justify-center text-xl md:text-3xl animate-pulse ring-4 md:ring-8 ring-red-500/10">📞</div>
                    <div>
                      <h4 className="text-white font-black text-xl md:text-2xl tracking-tighter">HOD OFFICE</h4>
                      <p className="text-red-500 text-[10px] md:text-xs font-black uppercase tracking-widest">Urgent Review</p>
                    </div>
                  </div>
                  <div className="flex gap-6 md:gap-8 w-full sm:w-auto justify-center">
                    <button onClick={() => setShowFakeCall(false)} className="w-14 h-14 md:w-16 md:h-16 rounded-full bg-red-600 flex items-center justify-center shadow-xl shadow-red-600/30 active:scale-90 transition-transform"><svg className="w-6 h-6 md:w-8 md:h-8 text-white" fill="currentColor" viewBox="0 0 20 20"><path d="M10 18a8 8 0 100-16 8 8 0 000 16zM7 9a1 1 0 000 2h6a1 1 0 100-2H7z"/></svg></button>
                    <button onClick={async () => { setCallStatus('connected'); stopAllSounds(); await playHODVoice(); setTimeout(() => setShowFakeCall(false), 9000); }} className="w-14 h-14 md:w-16 md:h-16 rounded-full bg-green-500 flex items-center justify-center animate-bounce shadow-xl shadow-green-500/30 active:scale-90 transition-transform"><svg className="w-6 h-6 md:w-8 md:h-8 text-white" fill="currentColor" viewBox="0 0 20 20"><path d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z"/></svg></button>
                  </div>
                </>
              ) : (
                <div className="w-full flex items-center justify-center py-4 md:py-6">
                   <div className="text-center space-y-2">
                      <h4 className="text-green-400 font-black text-[10px] md:text-xs tracking-[0.4em] uppercase">Encrypted Connection Established</h4>
                      <p className="text-white text-lg md:text-xl font-black uppercase animate-pulse">FACULTY STREAM ACTIVE</p>
                   </div>
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>
    </AnimatePresence>
  );
}
